// comp_coverage.sv
// Functional coverage subscriber for the comparator
class comp_coverage extends uvm_subscriber #(comp_seq_item);

  `uvm_component_utils(comp_coverage)

  comp_seq_item txn;

  // Covergroup definition
  covergroup comp_cg;
    option.per_instance = 1;
    option.name = "comp_cg";

    // Coverpoints for inputs
    cp_a: coverpoint txn.a {
      bins zero    = {2'b00};
      bins one     = {2'b01};
      bins two     = {2'b10};
      bins three   = {2'b11};
    }

    cp_b: coverpoint txn.b {
      bins zero    = {2'b00};
      bins one     = {2'b01};
      bins two     = {2'b10};
      bins three   = {2'b11};
    }

    // Coverpoints for outputs
    cp_agreaterb: coverpoint txn.agreaterb {
      bins high = {1'b1};
      bins low  = {1'b0};
    }

    cp_aequalb: coverpoint txn.aequalb {
      bins high = {1'b1};
      bins low  = {1'b0};
    }

    cp_alesserb: coverpoint txn.alesserb {
      bins high = {1'b1};
      bins low  = {1'b0};
    }

    // Comparison result coverpoint
    cp_result: coverpoint {txn.agreaterb, txn.aequalb, txn.alesserb} {
      bins greater = {3'b100};
      bins equal   = {3'b010};
      bins lesser  = {3'b001};
      illegal_bins invalid = default;
    }

    // Cross-coverage: all input combinations
    cx_a_b: cross cp_a, cp_b;

    // Cross-coverage: inputs vs result
    cx_a_result: cross cp_a, cp_result;
    cx_b_result: cross cp_b, cp_result;

    // Cross-coverage: full input space vs output result
    cx_full: cross cp_a, cp_b, cp_result;

    // Boundary cases
    cp_boundary: coverpoint {txn.a, txn.b} {
      bins both_zero     = {4'b0000};
      bins both_max      = {4'b1111};
      bins a_zero_b_max  = {4'b0011};
      bins a_max_b_zero  = {4'b1100};
      bins a_eq_b_mid1   = {4'b0101};
      bins a_eq_b_mid2   = {4'b1010};
    }
  endgroup

  function new(string name = "comp_coverage", uvm_component parent = null);
    super.new(name, parent);
    comp_cg = new();
  endfunction

  virtual function void write(comp_seq_item t);
    txn = t;
    comp_cg.sample();
    `uvm_info(get_type_name(), $sformatf("Coverage sampled: a=%0d b=%0d", txn.a, txn.b), UVM_HIGH)
  endfunction

  virtual function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), $sformatf("Functional Coverage: %.2f%%", comp_cg.get_inst_coverage()), UVM_NONE)
  endfunction

endclass

