// tb_top.sv
// Top-level testbench module
`timescale 1ns/1ps

module tb_top;
  // Clock generation (for UVM scheduling, even though DUT is combinational)
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100MHz clock
  end

  // Instantiate the interface
  comp_if cif();

  // Instantiate the DUT, connecting through the interface
  comparator dut (
    .a         (cif.a),
    .b         (cif.b),
    .agreaterb (cif.agreaterb),
    .aequalb   (cif.aequalb),
    .alesserb  (cif.alesserb)
  );

  // Store virtual interface in config_db and start test
  initial begin
    uvm_config_db #(virtual comp_if)::set(null, "*", "vif", cif);
    run_test("comp_base_test");
  end

  // Timeout watchdog
  initial begin
    #10000000;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

  // Dump waveforms (optional, simulator-dependent)
  initial begin
    $dumpfile("comp_tb.vcd");
    $dumpvars(0, tb_top);
  end

endmodule

